    @Tag("boundary")
    public void testSplitWithEmptyString() {
        String input = "";
        LinkedList result = StringUtils.split(input);
        // Acceptable: empty LinkedList or LinkedList with one empty string
        assertTrue(((LinkedList)result).size() == 0 || (((LinkedList)result).size() == 1 && "".equals(((LinkedList)result).get(0))), "Should handle empty string input gracefully");
    }
