    @Tag("valid")
    public void testSplitWithSimpleDelimitedString() {
        String input = "a,b,c";
        LinkedList result = StringUtils.split(input);
        assertEquals(3, ((LinkedList)result).size(), "Should return three elements");
        assertEquals("a", ((LinkedList)result).get(0));
        assertEquals("b", ((LinkedList)result).get(1));
        assertEquals("c", ((LinkedList)result).get(2));
    }
    @Test
    @Tag("boundary")
    public void testSplitWithConsecutiveDelimiters() {
        String input = "a,,b,,c";
        LinkedList result = StringUtils.split(input);
        assertEquals(5, ((LinkedList)result).size(), "Should handle consecutive delimiters (producing empty elements)");
        assertEquals("a", ((LinkedList)result).get(0));
        assertEquals("", ((LinkedList)result).get(1));
        assertEquals("b", ((LinkedList)result).get(2));
        assertEquals("", ((LinkedList)result).get(3));
        assertEquals("c", ((LinkedList)result).get(4));
    }
    @Test
    @Tag("boundary")
    public void testSplitWithLeadingAndTrailingDelimiters() {
        String input = ",a,b,";
        LinkedList result = StringUtils.split(input);
        assertEquals(4, ((LinkedList)result).size(), "Should handle leading and trailing delimiters");
        assertEquals("", ((LinkedList)result).get(0));
        assertEquals("a", ((LinkedList)result).get(1));
        assertEquals("b", ((LinkedList)result).get(2));
        assertEquals("", ((LinkedList)result).get(3));
    }
